<main class="page-shell">
    <header class="section-heading"><p class="eyebrow">Campus resources</p><h1>Facilities</h1><p>Explore the workshops, laboratories and learning spaces that support practical training at SLGTI.</p></header>
    <form class="public-filter" method="get"><select name="category" aria-label="Filter by facility category"><option value="">All categories</option><?php foreach ($categories as $item): ?><option value="<?= e($item['category']) ?>" <?= $category === $item['category'] ? 'selected' : '' ?>><?= e($item['category']) ?></option><?php endforeach; ?></select><button class="button" type="submit">Filter</button></form>
    <div class="facility-public-grid"><?php foreach ($facilities as $facility): ?><article class="facility-public-card"><?php if ($facility['image']): ?><img src="<?= e(media_url($facility['image'])) ?>" alt="<?= e($facility['image_alt'] ?: $facility['title']) ?>" loading="lazy" width="640" height="420"><?php else: ?><span class="facility-public-placeholder"><i class="bi bi-building"></i></span><?php endif; ?><div><span class="facility-category"><?= e($facility['category'] ?: 'Campus facility') ?></span><h2><a href="<?= e(url('facilities/' . $facility['slug'])) ?>"><?= e($facility['title']) ?></a></h2><p><?= e($facility['summary']) ?></p><?php if ($facility['location'] || $facility['capacity']): ?><small><?= e($facility['location'] ?: '') ?><?= $facility['capacity'] ? ' · Capacity: ' . e($facility['capacity']) : '' ?></small><?php endif; ?></div></article><?php endforeach; ?></div>
    <?php if (!$facilities): ?><p>No facilities are currently available.</p><?php endif; ?>
</main>
